/**
 * @brief Based on LIBRA version, disables unneeded widgets and connects those
 *        with complementary functions.
 *
 * @note Only used in constructor - placed in own function to improve readability.
 */
void MainWindow::ConfigureUi() {
    ui_->a_debug_mode->setChecked(debug_mode_);

    // Display build configuration: LIBRA_VERSION
    {
        QString ver_text = "<span>";
#ifdef LIBRA_VERSION
        ver_text += QString("<b>%1</b>").arg(LIBRA_VERSION);
#else
        ver_text += "<b>Unsupported</b>";
#endif
        ver_text += "</span>";
        ui_->l_libraversion_val->setText(ver_text);
    }

    // Display build configuration: BUILD_WITH_ROS2
    {
        QString ros2en_text = "<span>";
#ifdef BUILD_WITH_ROS2
        ros2en_text += "<b style='color: green;'>ON</b>";
#else
        ros2en_text += "<b style='color: red;'>OFF</b>";
#endif
        ros2en_text += "</span>";
        ui_->l_ros2enabled_val->setText(ros2en_text);
    }

    // ========== Menu Bar ==========

    // Unneeded menus/actions
#if LIBRA_VERSION != 1
    ui_->m_serial_servo->setEnabled(false);
#elif LIBRA_VERSION != 2
    ui_->m_epos->setEnabled(false);
#endif

    // Slots
    //   (none)

    // ========== Arm ==========

    // Unneeded widgets
#if LIBRA_VERSION != 1
    RemoveUiElement(ui_->gl_roll_input);
    RemoveUiElement(ui_->gl_roll_output);

    RemoveUiElement(ui_->gl_j1_input);
    RemoveUiElement(ui_->gl_j1_output);

    RemoveUiElement(ui_->gl_j2_input);
    RemoveUiElement(ui_->gl_j2_output);

    RemoveUiElement(ui_->gl_j3_input);
    RemoveUiElement(ui_->gl_j3_output);
#elif LIBRA_VERSION != 2
    RemoveUiElement(ui_->gl_yaw_input);
    RemoveUiElement(ui_->gl_yaw_output);

    RemoveUiElement(ui_->l_epos_status);
#endif

    // Slots
    connect(ui_->hs_arm_pitch, &QAbstractSlider::sliderMoved,  // when moved,
            ui_->sb_arm_pitch, &QDoubleSpinBox::setValue);     // update display
    connect(ui_->sb_arm_pitch, &QDoubleSpinBox::valueChanged,  // when changed,
            ui_->hs_arm_pitch, &QAbstractSlider::setValue);    // update slider

#if LIBRA_VERSION == 1
    connect(ui_->hs_arm_roll, &QAbstractSlider::sliderMoved,  // "
            ui_->sb_arm_roll, &QDoubleSpinBox::setValue);
    connect(ui_->sb_arm_roll, &QDoubleSpinBox::valueChanged,  // "
            ui_->hs_arm_roll, &QAbstractSlider::setValue);

    connect(ui_->hs_arm_j1, &QAbstractSlider::sliderMoved,  // "
            ui_->sb_arm_j1, &QDoubleSpinBox::setValue);
    connect(ui_->sb_arm_j1, &QDoubleSpinBox::valueChanged,  // "
            ui_->hs_arm_j1, &QAbstractSlider::setValue);

    connect(ui_->hs_arm_j2, &QAbstractSlider::sliderMoved,  // "
            ui_->sb_arm_j2, &QDoubleSpinBox::setValue);
    connect(ui_->sb_arm_j2, &QDoubleSpinBox::valueChanged,  // "
            ui_->hs_arm_j2, &QAbstractSlider::setValue);

    connect(ui_->hs_arm_j3, &QAbstractSlider::sliderMoved,  // "
            ui_->sb_arm_j3, &QDoubleSpinBox::setValue);
    connect(ui_->sb_arm_j3, &QDoubleSpinBox::valueChanged,  // "
            ui_->hs_arm_j3, &QAbstractSlider::setValue);
#elif LIBRA_VERSION == 2
    connect(ui_->hs_arm_yaw, &QAbstractSlider::sliderMoved,  // "
            ui_->sb_arm_yaw, &QDoubleSpinBox::setValue);
    connect(ui_->sb_arm_yaw, &QDoubleSpinBox::valueChanged,  // "
            ui_->hs_arm_yaw, &QAbstractSlider::setValue);
#endif

    // Store original limits for override functionality
    original_limits_.pitch_min = ui_->sb_arm_pitch->minimum();
    original_limits_.pitch_max = ui_->sb_arm_pitch->maximum();

#if LIBRA_VERSION == 1
    original_limits_.roll_min = ui_->sb_arm_roll->minimum();
    original_limits_.roll_max = ui_->sb_arm_roll->maximum();

    original_limits_.j1_min = ui_->sb_arm_j1->minimum();
    original_limits_.j1_max = ui_->sb_arm_j1->maximum();

    original_limits_.j2_min = ui_->sb_arm_j2->minimum();
    original_limits_.j2_max = ui_->sb_arm_j2->maximum();

    original_limits_.j3_min = ui_->sb_arm_j3->minimum();
    original_limits_.j3_max = ui_->sb_arm_j3->maximum();
#elif LIBRA_VERSION == 2
    original_limits_.yaw_min = ui_->sb_arm_yaw->minimum();
    original_limits_.yaw_max = ui_->sb_arm_yaw->maximum();
#endif

    // Set up validation for the "Quick Input" Line Edit
    {
        // Explanation of the regex:
        // - "^-?": optional minus sign
        // - "\d{1,3}": 1–3 digit number
        // - "(,-?\d{1,3}){0,4}": up to 4 more integers, each preceded by a comma
        QRegularExpression regex("(^-?\\d{1,3}(,-?\\d{1,3}){0,4}$)");
        QRegularExpressionValidator* validator =
            new QRegularExpressionValidator(regex, this);
        ui_->le_quick_input->setValidator(validator);
    }

    // ========== Water ==========

    // Unneeded widgets
#if LIBRA_VERSION != 1
    RemoveUiElement(ui_->vl_counterweight_B);
    RemoveUiElement(ui_->pb_water_fill_B);
    RemoveUiElement(ui_->pb_water_drain_B);
#endif

    // Slots
    //   (none)

    // ========== Manipulator ==========

    // Unneeded widgets
#if LIBRA_VERSION != 1
    RemoveUiElement(ui_->gb_manipulator);
#endif

    // Slots
#if LIBRA_VERSION == 1
    //   (none)
#endif

    // ========== Camera ==========

    connect(ui_->pb_camera_refresh, &QPushButton::clicked,     // when clicked,
            ui_->a_refresh_camera_list, &QAction::triggered);  // refresh list
}

