/**
 * @brief Sets up child objects.
 *
 * @note Only used in constructor - placed in own function to improve readability.
 */
void MainWindow::InitializeDeviceManagers() {
    // ========== Arduino Manager ==========

    // NOTE: Since ArduinoManager is QTimer-driven and asynchronous, we set up
    //       signal/slot connections much like we do with QThreads. This is not
    //       necessary with CameraManager, which is different by nature.

    arduino_manager_ = new ArduinoManager(this, debug_mode_);

    // MainWindow signals
    connect(this, &MainWindow::EnableDebugMode,  // update debug mode
            arduino_manager_, &ArduinoManager::SetDebugMode);

    connect(this, &MainWindow::ConnectWater,  // connect water
            arduino_manager_, &ArduinoManager::ConnectWater);
    connect(ui_->a_water_disconnect, &QAction::triggered,  // disconnect water
            arduino_manager_, &ArduinoManager::DisconnectWater);
    connect(this, &MainWindow::EnableAutoTorqueComp,  // automate water state
            arduino_manager_, &ArduinoManager::SetAutoCompensation);
    connect(this, &MainWindow::CommandWater,  // force update water command
            arduino_manager_, &ArduinoManager::ForceWaterCommand);

#if LIBRA_VERSION == 1
    connect(this, &MainWindow::ConnectManip,  // connect servos
            arduino_manager_, &ArduinoManager::ConnectManip);
    connect(ui_->a_manip_disconnect, &QAction::triggered,  // disconnect servos
            arduino_manager_, &ArduinoManager::DisconnectManip);
    connect(ui_->a_manip_enable_auto_correction, &QAction::toggled,  // leveling
            arduino_manager_, &ArduinoManager::SetManipCorrectionEnabled);
    connect(this, &MainWindow::CommandManip,  // update manip targets
            arduino_manager_, &ArduinoManager::SetManipTarget);
#endif

    // TankWidget signals
    connect(ui_->tw_water_level_A, &TankWidget::TankFull,  // stop if full
            this, [this]() {
                logger_->Info("Tank A estimated full; disabling ATC");
                ui_->pb_autocomp_enable->setChecked(false);
            });

    connect(ui_->tw_water_level_A, &TankWidget::TankEmpty,  // stop if empty
            this, [this]() {
                logger_->Info("Tank A estimated empty; disabling ATC");
                ui_->pb_autocomp_enable->setChecked(false);
            });

#if LIBRA_VERSION == 1
    connect(ui_->tw_water_level_B, &TankWidget::TankFull,  // stop if full
            this, [this]() {
                logger_->Info("Tank B estimated full; disabling ATC");
                ui_->pb_autocomp_enable->setChecked(false);
            });

    connect(ui_->tw_water_level_B, &TankWidget::TankEmpty,  // stop if empty
            this, [this]() {
                logger_->Info("Tank B estimated empty; disabling ATC");
                ui_->pb_autocomp_enable->setChecked(false);
            });
#endif

    // MainWindow slots
    connect(arduino_manager_, &ArduinoManager::ErrorThrown,  // handle errors
            this, &MainWindow::HandleCriticalError);

    connect(arduino_manager_, &ArduinoManager::WaterConnected,  // update UI
            this, &MainWindow::HandleWaterConnChanged);
    connect(arduino_manager_, &ArduinoManager::ReportWaterStatus,  // get state
            this, &MainWindow::HandleWaterStatus);

#if LIBRA_VERSION == 1
    connect(arduino_manager_, &ArduinoManager::ManipConnected,  // update UI
            this, &MainWindow::HandleManipConnChanged);
    connect(arduino_manager_, &ArduinoManager::ReportPosition,  // get position
            this, &MainWindow::HandleManipPosition);
#endif

    // ========== Camera Manager ==========

    // TODO: auto-display first connected device?
}

/**
 * @brief Sets up signal and slot connections to child threads and spins them up.
 *
 * @note In Qt, thread management for subclassed QThreads generally has 4 steps:
 *   1) Initialize a new QThread object as a child of MainWindow.
 *   2) Register its signals and slots to send/receive data to/from MainWindow.
 *   3) Register its exit signal to its own destruction slot.
 *   4) Spin it off.
 * If the thread loops continuously, there is a fifth step:
 *   5) In the MainWindow destructor, interrupt or forcibly stop the QThread.
 *
 * @note Only used in constructor - placed in own function to improve readability.
 */
void MainWindow::InitializeThreads() {
    // ========== HEBI Thread ==========

    // NOTE: This constructor automatically determines the actuator family and
    //       names based on the LIBRA_VERSION the app is built with
    hebi_thread_ = new HebiThread(this, debug_mode_);

    // MainWindow signals
    connect(this, &MainWindow::EnableDebugMode,  // update debug mode
            hebi_thread_, &HebiThread::SetDebugMode);

    connect(ui_->a_hebi_connect, &QAction::triggered,  // connect to HEBI
            hebi_thread_, &HebiThread::Connect);
    connect(ui_->a_hebi_disconnect, &QAction::triggered,  // disconnect HEBI
            hebi_thread_, &HebiThread::Disconnect);

    connect(this, &MainWindow::CommandHebi,  // update HEBI target(s)
            hebi_thread_, &HebiThread::SetTarget);
    connect(ui_->pb_arm_stop, &QPushButton::clicked,  // stop ALL actuators
            hebi_thread_, &HebiThread::Stop);

    connect(this, &MainWindow::LoadHebiGains,  // load new gains
            hebi_thread_, &HebiThread::LoadGains);
    connect(ui_->a_hebi_log_start, &QAction::triggered,  // start new hebilog
            hebi_thread_, &HebiThread::StartHebiLog);
    connect(ui_->a_hebi_log_stop, &QAction::triggered,  // stop current hebilog
            hebi_thread_, &HebiThread::StopHebiLog);

    connect(this, &MainWindow::EnableAutoTorqueComp,  // auto-balancing
            hebi_thread_, &HebiThread::EnableTorqueControl);
    connect(this, &MainWindow::UpdateHebiTorqueCompBounds,  // update limits
            hebi_thread_, &HebiThread::SetTorqueCompBounds);
    connect(ui_->a_hebi_model_based_comp, &QAction::toggled,  // HRDF-based comp
            hebi_thread_, &HebiThread::EnableModelBasedComp);

    // MainWindow slots
    connect(hebi_thread_, &HebiThread::ErrorThrown,  // handle errors
            this, &MainWindow::HandleCriticalError);

    connect(hebi_thread_, &HebiThread::Connected,  // update UI
            this, &MainWindow::HandleHebiConnChanged);
    connect(hebi_thread_, &HebiThread::ReportFeedback,  // get feedback
            this, &MainWindow::HandleActuatorFeedback);
    connect(hebi_thread_, &HebiThread::ReportStatus,  // get minor statuses
            this, &MainWindow::HandleActuatorStatus);

    // ArduinoManager slots
    connect(hebi_thread_, &HebiThread::ReportArmTorque,  // update water command
            arduino_manager_, &ArduinoManager::UpdateWaterControl);
#if LIBRA_VERSION == 1
    connect(hebi_thread_, &HebiThread::InformPitch,  // update manip correction
            arduino_manager_, &ArduinoManager::SetManipCorrection);
#endif

    // Thread cleanup
    connect(hebi_thread_, &HebiThread::finished,      // when thread exits,
            hebi_thread_, &HebiThread::deleteLater);  // deallocate

    hebi_thread_->start();

    // ========== EPOS Thread ==========

#if LIBRA_VERSION == 2
    epos_thread_ = new EposThread(this, debug_mode_);

    // MainWindow signals
    connect(this, &MainWindow::EnableDebugMode,  // update debug mode
            epos_thread_, &EposThread::SetDebugMode);

    connect(this, &MainWindow::ConnectEpos,  // connect to EPOS
            epos_thread_, &EposThread::Connect);
    connect(ui_->a_epos_disconnect, &QAction::triggered,  // disconnect EPOS
            epos_thread_, &EposThread::Disconnect);

    connect(this, &MainWindow::CommandEpos,  // update EPOS target(s)
            epos_thread_, &EposThread::SetTarget);
    connect(ui_->pb_arm_stop, &QPushButton::clicked,  // stop ALL actuators
            epos_thread_, &EposThread::Stop);

    // MainWindow slots
    connect(epos_thread_, &EposThread::ErrorThrown,  // handle errors
            this, &MainWindow::HandleCriticalError);

    connect(epos_thread_, &EposThread::Connected,  // update UI
            this, &MainWindow::HandleEposConnChanged);
    connect(epos_thread_, &EposThread::ReportFeedback,  // get feedback
            this, &MainWindow::HandleActuatorFeedback);
    connect(epos_thread_, &EposThread::ReportStatus,  // get minor statuses
            this, &MainWindow::HandleActuatorStatus);

    // Thread cleanup
    connect(epos_thread_, &EposThread::finished,      // when thread exits,
            epos_thread_, &EposThread::deleteLater);  // deallocate

    epos_thread_->start();
#endif
}

/**
 * @brief Update UI according to connection status of all actuator types.
 */
void MainWindow::UpdateActuatorControls() {
    // Evaluate connection statuses of all actuators
    bool hebi_connected = ui_->a_hebi_disconnect->isEnabled();
    bool any_connected = hebi_connected;

#if LIBRA_VERSION == 2
    bool epos_connected = ui_->a_epos_disconnect->isEnabled();
    any_connected = hebi_connected || epos_connected;
#endif

    // Update UI
    ui_->pb_arm_start->setEnabled(any_connected);
    ui_->le_quick_input->setEnabled(any_connected);
    ui_->pb_quick_input->setEnabled(any_connected);
    ui_->pb_arm_stop->setEnabled(any_connected);
}

