/**
 * @brief Reflects SerialWater connection status in the UI.
 */
void MainWindow::HandleWaterConnChanged(const bool& connected) {
    // Menu bar
    ui_->a_water_connect->setEnabled(!connected);
    ui_->a_water_disconnect->setEnabled(connected);

    ui_->a_water_set_empty->setEnabled(connected);
    ui_->a_water_set_full->setEnabled(connected);

    // UI widgets
    ui_->pb_water_fill_A->setEnabled(connected);
    ui_->pb_water_drain_A->setEnabled(connected);
#if LIBRA_VERSION == 1
    ui_->pb_water_fill_B->setEnabled(connected);
    ui_->pb_water_drain_B->setEnabled(connected);
#endif

    if (connected || (!connected && ui_->a_hebi_connect->isEnabled())) {
        // Since auto torque compensation is shared between ActuatorThread and
        // ArduinoManager, disable this button if neither is connected
        ui_->pb_autocomp_enable->setEnabled(connected);
    }
}

/**
 * @brief Reflects fluid system status in the UI.
 *        - Primary visual feedback: formatted status string in "WATER" GroupBox
 *        - Secondary visual feedback: updates animation state of TankWidget(s)
 *
 * @param side The side of the fluid system
 * @param state The flow state of the fluid system
 */
void MainWindow::HandleWaterStatus(const Water::Side& side,
                                   const Water::State& state) {
    switch (side) {
        case Water::Side::kA:
            ui_->l_water_status_A->setText(Water::StateEnumToString(state));
            ui_->tw_water_level_A->UpdateState(state);
            break;
#if LIBRA_VERSION == 1
        case Water::Side::kB:
            ui_->l_water_status_B->setText(Water::StateEnumToString(state));
            ui_->tw_water_level_B->UpdateState(state);
            break;
#endif
        default:
            // Shouldn't be able to get here
            logger_->Error("Received status for unknown fluid system side: "
                           + SideEnumToString(side) + " ("
                           + std::to_string(static_cast<int>(side)) + ")");
    }
}

/**
 * @brief Reflects HEBI actuator connection status in the UI.
 */
void MainWindow::HandleHebiConnChanged(const bool& connected) {
    // Menu bar
    ui_->a_hebi_connect->setEnabled(!connected);
    ui_->a_hebi_disconnect->setEnabled(connected);

    ui_->a_hebi_load_gains->setEnabled(connected);
    ui_->a_hebi_log_start->setEnabled(connected);
    ui_->a_hebi_log_stop->setEnabled(connected);

    ui_->a_hebi_override_limits->setEnabled(connected);
    ui_->a_hebi_central_torque_comp->setEnabled(connected);
    ui_->a_hebi_model_based_comp->setEnabled(connected);

    // UI widgets
    UpdateActuatorControls();

    if (connected || (!connected && ui_->a_water_connect->isEnabled())) {
        // Since auto torque compensation is shared between ActuatorThread and
        // ArduinoManager, disable this button if neither is connected
        ui_->pb_autocomp_enable->setEnabled(connected);
    }
}

#if LIBRA_VERSION == 2
/**
 * @brief Reflects EPOS (Maxon) actuator connection status in the UI.
 */
void MainWindow::HandleEposConnChanged(const bool& connected) {
    // Menu bar
    ui_->a_epos_connect->setEnabled(!connected);
    ui_->a_epos_usedefaults->setEnabled(!connected);
    ui_->a_epos_disconnect->setEnabled(connected);

    // UI widgets
    UpdateActuatorControls();
}
#endif

/**
 * @brief Sorts important actuator information into individual UI elements.
 *
 * @param feedbacks Unordered map of joint(s) and their corresponding feedback
 * @param feedback_type The type of primary feedback provided
 *
 * @note To improve ease of use, LIBRA-I arm actuator angles (J1, J2, J3) in the
 *       UI are shown relative to a forward-facing perspective directly behind
 *       the robot, where "0" is directly forward, and counterclockwise movement
 *       is considered "+" (positive).
 */
void MainWindow::HandleActuatorFeedback(
    const std::unordered_map<Joint::Name, double>& feedbacks,
    const Actuator::Feedback feedback_type) {
    bool initialized = false;

    for (const auto& feedback : feedbacks) {
        const auto& joint = feedback.first;
        const auto& val = feedback.second;

        // Index into matching label using map-of-maps initialized in constructor
        try {
            feedback_element_map_.at(joint)
                .at(feedback_type)
                ->setText(QString::number(val, 'f', kPrecision));
        } catch (const std::out_of_range&) {
            logger_->Error(
                "No UI element mapped to joint " + Joint::NameEnumToString(joint)
                + " (" + std::to_string(static_cast<int>(joint))
                + ") and feedback type "
                + Actuator::FeedbackEnumToString(feedback_type) + " ("
                + std::to_string(static_cast<int>(feedback_type)) + ")");
        }

        // TODO: documentation
        if (!initialized) {
            // TODO: initialize SpinBoxes to first received value

            initialized = true;
        }
    }
}

/**
 * @brief Prints miscellaneous actuator information at the bottom of the UI.
 *
 * @param status Newline-delimited status info
 * @param type The actuator type, for updating the corresponding UI element
 */
void MainWindow::HandleActuatorStatus(const QString& status,
                                      const Actuator::Type type) {
    switch (type) {
        case Actuator::Type::kHebi:
            ui_->l_hebi_status->setText(status);
            break;
#if LIBRA_VERSION == 2
        case Actuator::Type::kEpos:
            ui_->l_epos_status->setText(status);
            break;
#endif
        default:
            // Shouldn't be able to get here
            logger_->Error("Received status from unknown actuator type: "
                           + TypeEnumToString(type) + " ("
                           + std::to_string(static_cast<int>(type)) + ")");
    }
}

/**
 * @brief Throws a pop-up error box upon receiving an error signal from a thread.
 *
 * @param err Fatal error message from a component
 */
void MainWindow::HandleCriticalError(const QString& err) {
    QMessageBox::critical(this, tr("Error"), err);
}

